# DOC001-DOC020: Constitution of India (condensed paraphrases of public government text)
SRC = "Constitution of India (Government of India, Legislative Department)"
URL = "https://legislative.gov.in"
DOCS = [
dict(title="Preamble to the Constitution of India",
text="""The Preamble to the Constitution of India is the introductory statement that sets out the philosophy and objectives of the Constitution. It begins with the words "We, the People of India" and declares the resolve to constitute India into a sovereign, socialist, secular, democratic republic. The words socialist and secular were inserted by the 42nd Amendment Act of 1976, which also changed "unity of the Nation" to "unity and integrity of the Nation". The Preamble secures to all citizens justice (social, economic and political), liberty (of thought, expression, belief, faith and worship), equality (of status and of opportunity) and fraternity assuring the dignity of the individual. The Constituent Assembly adopted the Constitution on 26 November 1949, and it came into force on 26 January 1950, which is celebrated every year as Republic Day. In Kesavananda Bharati v. State of Kerala (1973) the Supreme Court held that the Preamble is part of the Constitution.""",
qa=[("When did the Constitution of India come into force?","26 January 1950","factual"),
("Which amendment inserted the words socialist and secular into the Preamble?","42nd Amendment Act of 1976","factual"),
("What ideals does the Preamble secure to all citizens?","justice (social, economic and political), liberty (of thought, expression, belief, faith and worship), equality (of status and of opportunity) and fraternity","summarization")]),
dict(title="The Union and its Territory (Articles 1-4)",
text="""Part I of the Constitution, Articles 1 to 4, deals with the Union and its territory. Article 1 states that India, that is Bharat, shall be a Union of States. The phrase Union of States was chosen because the Indian federation is not the result of an agreement between states and no state has the right to secede from it. The territory of India comprises the territories of the States, the Union territories and any other territories that may be acquired. Under Article 3, Parliament may by law form a new State, increase or diminish the area of a State, alter the boundaries of a State or change its name. A Bill for this purpose can be introduced only on the recommendation of the President, and the President must refer it to the concerned State Legislature for its views, although Parliament is not bound by those views. Article 2 allows Parliament to admit or establish new States, and Article 4 clarifies that such laws are not constitutional amendments under Article 368.""",
qa=[("What does Article 1 say India is?","a Union of States","factual"),
("Which article lets Parliament form new States or alter state boundaries?","Under Article 3","procedural"),
("Is Parliament bound by the views of a State Legislature on a bill altering its boundaries?","Parliament is not bound by those views","analytical")]),
dict(title="Citizenship (Articles 5-11)",
text="""Part II of the Constitution, Articles 5 to 11, deals with citizenship. Article 5 declared who were citizens at the commencement of the Constitution: persons domiciled in India who were born in India, or whose parent was born in India, or who had been ordinarily resident in India for at least five years. Articles 6 and 7 dealt with migrants from Pakistan, and Article 8 with persons of Indian origin residing abroad. Article 9 provides that a person who voluntarily acquires the citizenship of a foreign State ceases to be a citizen of India. Article 11 empowers Parliament to regulate the right of citizenship by law, and Parliament exercised this power by enacting the Citizenship Act, 1955, which lays down how citizenship may be acquired: by birth, by descent, by registration, by naturalisation and by incorporation of territory. India follows a system of single citizenship, so there is no separate state citizenship, and the Overseas Citizen of India card is not dual citizenship.""",
qa=[("Which article empowers Parliament to regulate citizenship by law?","Article 11","factual"),
("Does India allow dual citizenship?","India follows a system of single citizenship","analytical"),
("In what ways can citizenship be acquired under the Citizenship Act, 1955?","by birth, by descent, by registration, by naturalisation and by incorporation of territory","procedural")]),
dict(title="Fundamental Rights: Overview and Right to Equality (Articles 12-18)",
text="""Part III of the Constitution (Articles 12 to 35) guarantees the Fundamental Rights, which are enforceable by the courts. Article 12 defines the State, and Article 13 declares that laws inconsistent with Fundamental Rights are void to the extent of the inconsistency. Originally seven in number, the Fundamental Rights are now six groups because the right to property was removed from Part III by the 44th Amendment in 1978 and became a legal right under Article 300A. The Right to Equality covers Articles 14 to 18. Article 14 guarantees equality before the law and the equal protection of the laws. Article 15 prohibits discrimination only on grounds of religion, race, caste, sex or place of birth. Article 16 ensures equality of opportunity in public employment. Article 17 abolishes untouchability and makes its practice an offence, and Article 18 abolishes titles other than military and academic distinctions.""",
qa=[("Which article abolishes untouchability?","Article 17","factual"),
("Which amendment removed the right to property from the Fundamental Rights?","44th Amendment in 1978","factual"),
("On which grounds does Article 15 prohibit discrimination?","religion, race, caste, sex or place of birth","summarization")]),
dict(title="Right to Freedom (Articles 19-22)",
text="""The Right to Freedom is contained in Articles 19 to 22. Article 19(1) guarantees six freedoms to citizens: freedom of speech and expression, freedom to assemble peaceably and without arms, freedom to form associations or unions or cooperative societies, freedom to move freely throughout India, freedom to reside and settle in any part of India, and freedom to practise any profession or carry on any occupation, trade or business. These freedoms are subject to reasonable restrictions. Article 20 gives protection in respect of conviction for offences: no ex post facto criminal law, no double jeopardy and no compulsion to be a witness against oneself. Article 21 provides that no person shall be deprived of life or personal liberty except according to procedure established by law, and Article 21A, inserted by the 86th Amendment in 2002, makes free and compulsory education a right for children aged six to fourteen. Article 22 protects persons who are arrested or detained, including the right to be informed of the grounds of arrest, to consult a lawyer and to be produced before a magistrate within 24 hours.""",
qa=[("Which article protects life and personal liberty?","Article 21","factual"),
("Within how many hours must an arrested person be produced before a magistrate?","within 24 hours","factual"),
("Which age group does Article 21A cover for free and compulsory education?","children aged six to fourteen","factual")]),
dict(title="Rights against Exploitation, Freedom of Religion, Cultural and Educational Rights (Articles 23-30)",
text="""Article 23 prohibits traffic in human beings and forced labour, known as begar. Article 24 forbids the employment of children below the age of fourteen in factories, mines or other hazardous work. The Right to Freedom of Religion is contained in Articles 25 to 28. Article 25 guarantees freedom of conscience and the right to freely profess, practise and propagate religion, subject to public order, morality and health. Article 26 allows every religious denomination to manage its own religious affairs. Article 27 says no person can be compelled to pay taxes for the promotion of any particular religion, and Article 28 regulates religious instruction in educational institutions that are wholly maintained by the State. Cultural and Educational Rights are in Articles 29 and 30. Article 29 protects the interests of minorities by giving any section of citizens the right to conserve its distinct language, script or culture, while Article 30 gives minorities, based on religion or language, the right to establish and administer educational institutions of their choice.""",
qa=[("What does Article 24 prohibit?","employment of children below the age of fourteen in factories, mines or other hazardous work","factual"),
("Which article gives minorities the right to establish and administer educational institutions?","Article 30","factual"),
("How do Article 29 and Article 30 differ?","Article 29 protects the interests of minorities by giving any section of citizens the right to conserve its distinct language, script or culture, while Article 30","comparative")]),
dict(title="Right to Constitutional Remedies and Writs (Articles 32 and 226)",
text="""Article 32 gives every person the right to move the Supreme Court directly for the enforcement of Fundamental Rights, and Dr B. R. Ambedkar described it as the heart and soul of the Constitution. The Supreme Court has the power to issue directions, orders or writs, including five kinds of writs: habeas corpus, mandamus, prohibition, certiorari and quo warranto. Habeas corpus requires a detained person to be produced before the court, mandamus commands a public authority to perform its legal duty, prohibition stops a lower court from exceeding its jurisdiction, certiorari quashes an order made without jurisdiction, and quo warranto questions a person's right to hold a public office. Article 226 gives the High Courts the power to issue writs not only for Fundamental Rights but also for any other purpose, so the writ jurisdiction of a High Court is wider than that of the Supreme Court under Article 32. Article 32 is itself a Fundamental Right and cannot be suspended except during an Emergency as provided in the Constitution.""",
qa=[("What are the five kinds of writs?","habeas corpus, mandamus, prohibition, certiorari and quo warranto","factual"),
("What does the writ of mandamus do?","mandamus commands a public authority to perform its legal duty","factual"),
("Why is the writ jurisdiction of a High Court wider than that of the Supreme Court?","not only for Fundamental Rights but also for any other purpose","analytical")]),
dict(title="Directive Principles of State Policy (Articles 36-51)",
text="""Part IV of the Constitution, Articles 36 to 51, contains the Directive Principles of State Policy. Article 37 states that these principles are not enforceable by any court but are nevertheless fundamental in the governance of the country, and the State has a duty to apply them in making laws. They aim at a welfare state and social and economic democracy. Article 39 directs the State towards adequate means of livelihood, fair distribution of material resources and equal pay for equal work for men and women. Article 40 directs the State to organise village panchayats, Article 44 to secure a uniform civil code for citizens, Article 45 to provide early childhood care and education for children below six years, Article 48A to protect and improve the environment, and Article 50 to separate the judiciary from the executive. Article 51 promotes international peace and security. In Minerva Mills v. Union of India (1980) the Supreme Court held that harmony and balance between Fundamental Rights and Directive Principles is part of the basic structure of the Constitution.""",
qa=[("Are Directive Principles enforceable by courts?","not enforceable by any court","factual"),
("Which article of the Directive Principles speaks of a uniform civil code?","Article 44","factual"),
("How do Fundamental Rights differ from Directive Principles in enforceability?","not enforceable by any court but are nevertheless fundamental in the governance of the country","comparative")]),
dict(title="Fundamental Duties (Article 51A)",
text="""Part IVA of the Constitution contains a single article, Article 51A, which lists the Fundamental Duties of citizens. They were added by the 42nd Amendment in 1976 on the recommendation of the Swaran Singh Committee, and there were originally ten duties. The eleventh duty was added by the 86th Amendment in 2002 and requires a parent or guardian to provide opportunities for education to a child between six and fourteen years of age. The duties require citizens to abide by the Constitution and respect its ideals and institutions, the National Flag and the National Anthem; to cherish the noble ideals of the freedom struggle; to uphold the sovereignty, unity and integrity of India; to defend the country; to promote harmony and the spirit of common brotherhood; to value the rich heritage of the composite culture; to protect and improve the natural environment; to develop scientific temper and humanism; to safeguard public property and abjure violence; and to strive towards excellence. The Fundamental Duties are not directly enforceable by courts.""",
qa=[("Which committee recommended the Fundamental Duties?","Swaran Singh Committee","factual"),
("How many Fundamental Duties were there originally?","originally ten duties","factual"),
("What is the eleventh Fundamental Duty?","requires a parent or guardian to provide opportunities for education to a child between six and fourteen years of age","summarization")]),
dict(title="The President of India (Articles 52-62)",
text="""The Constitution provides for a President of India under Article 52, and Article 53 vests the executive power of the Union in the President, to be exercised directly or through officers subordinate to the President. The President is elected under Article 54 by an electoral college consisting of the elected members of both Houses of Parliament and the elected members of the Legislative Assemblies of the States, including the National Capital Territory of Delhi and Puducherry. The election follows the system of proportional representation by means of the single transferable vote, and the voting is by secret ballot. The President holds office for five years and is eligible for re-election. To be a candidate a person must be a citizen of India, must have completed thirty-five years of age and must be qualified for election as a member of the Lok Sabha. Under Article 61 the President can be removed by impeachment for violation of the Constitution, which requires a resolution passed by a majority of not less than two-thirds of the total membership of each House. The President also has the power to grant pardons under Article 72 and to promulgate ordinances under Article 123 when Parliament is not in session.""",
qa=[("What is the term of office of the President of India?","five years","factual"),
("What is the minimum age to be a candidate for President?","completed thirty-five years of age","factual"),
("How can the President be removed?","impeachment for violation of the Constitution","procedural")]),
dict(title="Vice-President and the Council of Ministers (Articles 63-78)",
text="""The Vice-President of India is elected under Article 66 by the members of an electoral college consisting of the members of both Houses of Parliament, using proportional representation by the single transferable vote and a secret ballot. The Vice-President must be a citizen of India aged at least thirty-five years and holds office for five years. The Vice-President is the ex-officio Chairman of the Rajya Sabha and acts as President when a vacancy occurs. Article 74 provides for a Council of Ministers headed by the Prime Minister to aid and advise the President, who must act in accordance with that advice, although the 44th Amendment lets the President ask the Council to reconsider its advice once. Under Article 75 the Prime Minister is appointed by the President and the other ministers are appointed on the advice of the Prime Minister. The Council of Ministers is collectively responsible to the Lok Sabha. The 91st Amendment in 2003 limited the total number of ministers, including the Prime Minister, to fifteen percent of the total strength of the Lok Sabha.""",
qa=[("Who is the ex-officio Chairman of the Rajya Sabha?","The Vice-President is the ex-officio Chairman of the Rajya Sabha","factual"),
("To whom is the Council of Ministers collectively responsible?","collectively responsible to the Lok Sabha","factual"),
("How many ministers can the Council of Ministers have?","fifteen percent of the total strength of the Lok Sabha","analytical")]),
dict(title="Parliament of India: Composition and Terms (Articles 79-122)",
text="""Under Article 79, Parliament consists of the President and two Houses, the Council of States (Rajya Sabha) and the House of the People (Lok Sabha). The Rajya Sabha has a maximum strength of 250 members, of whom 238 represent the States and Union territories and 12 are nominated by the President for special knowledge in literature, science, art and social service. It is a permanent House that is not subject to dissolution, and one-third of its members retire every second year, each member serving a term of six years. The Lok Sabha represents the people directly and has a maximum strength of 550 members, with 543 elected members at present. Its normal term is five years unless it is dissolved earlier. A candidate must be at least 25 years old for the Lok Sabha and 30 years old for the Rajya Sabha. The voting age was reduced from 21 to 18 years by the 61st Amendment in 1988. Under Article 85 not more than six months may intervene between two sessions of Parliament.""",
qa=[("How many members can the Rajya Sabha have at most?","maximum strength of 250 members","factual"),
("What is the minimum age to contest Lok Sabha and Rajya Sabha elections?","at least 25 years old for the Lok Sabha and 30 years old for the Rajya Sabha","comparative"),
("How often do Rajya Sabha members retire?","one-third of its members retire every second year","factual")]),
dict(title="Legislative Procedure, Money Bills and the Budget (Articles 107-122, 265-267)",
text="""An ordinary Bill can be introduced in either House of Parliament and must be passed by both Houses before it receives the assent of the President. If the Houses disagree, the President may summon a joint sitting under Article 108, which is presided over by the Speaker of the Lok Sabha. A Money Bill, defined in Article 110, can be introduced only in the Lok Sabha on the recommendation of the President. The Rajya Sabha may only make recommendations on a Money Bill and must return it within fourteen days, and the Lok Sabha may accept or reject those recommendations. The Speaker's decision whether a Bill is a Money Bill is final. Article 112 requires the President to lay an annual financial statement, known as the Budget, before Parliament each year. Article 265 provides that no tax shall be levied or collected except by authority of law. All revenues received by the Government of India are credited to the Consolidated Fund of India under Article 266, and Article 267 creates the Contingency Fund of India for unforeseen expenditure.""",
qa=[("Who presides over a joint sitting of Parliament?","presided over by the Speaker of the Lok Sabha","factual"),
("Within how many days must the Rajya Sabha return a Money Bill?","within fourteen days","factual"),
("Can the Rajya Sabha reject a Money Bill?","The Rajya Sabha may only make recommendations on a Money Bill","analytical")]),
dict(title="The Supreme Court of India (Articles 124-147)",
text="""The Supreme Court of India was established under Article 124 and sits in New Delhi. It originally consisted of the Chief Justice of India and seven other judges, and the Supreme Court (Number of Judges) Amendment Act of 2019 raised the sanctioned strength to 34, including the Chief Justice. Judges are appointed by the President and retire at the age of 65. A judge can be removed only on the grounds of proved misbehaviour or incapacity through an address by both Houses of Parliament, supported by a majority of the total membership and two-thirds of the members present and voting. The Court has original jurisdiction in disputes between the Centre and the States under Article 131, appellate jurisdiction in constitutional, civil and criminal matters, and advisory jurisdiction under Article 143 when the President refers a question of law. Article 141 makes the law declared by the Supreme Court binding on all courts in India, and Article 142 allows it to pass orders necessary for doing complete justice. It is a court of record under Article 129 and has the power of judicial review.""",
qa=[("At what age do Supreme Court judges retire?","retire at the age of 65","factual"),
("How many judges is the Supreme Court sanctioned to have?","raised the sanctioned strength to 34, including the Chief Justice","factual"),
("What is the advisory jurisdiction of the Supreme Court?","advisory jurisdiction under Article 143 when the President refers a question of law","summarization")]),
dict(title="State Executive, Legislature and High Courts (Articles 153-237)",
text="""Each State has a Governor under Article 153, who is appointed by the President under Article 155 and holds office during the pleasure of the President, usually for a term of five years. The Governor must be a citizen of India aged at least thirty-five years. The executive power of the State is exercised by the Governor with the aid and advice of a Council of Ministers headed by the Chief Minister under Article 163. The Chief Minister is appointed by the Governor and the Council of Ministers is collectively responsible to the Legislative Assembly. The Legislative Assembly of a State has not more than 500 and not less than 60 members, and its normal term is five years. Some States also have a Legislative Council. Every State has a High Court under Article 214, and Parliament may establish a common High Court for two or more States. High Court judges retire at the age of 62 under Article 217. Under Article 227 a High Court exercises superintendence over all courts and tribunals within its territorial jurisdiction.""",
qa=[("Who appoints the Governor of a State?","appointed by the President under Article 155","factual"),
("What is the retirement age of High Court judges?","retire at the age of 62","factual"),
("How many members can a State Legislative Assembly have?","not more than 500 and not less than 60 members","factual")]),
dict(title="Centre-State Relations and the Seventh Schedule (Articles 245-263)",
text="""Part XI of the Constitution distributes legislative powers between the Union and the States. Article 246 divides subjects into three lists in the Seventh Schedule. The Union List contains subjects on which only Parliament may legislate, such as defence, foreign affairs and railways. The State List contains subjects such as police, public order, public health and agriculture, on which State Legislatures legislate. The Concurrent List contains subjects such as education, forests, marriage and criminal law, on which both can legislate, and if a State law conflicts with a Union law on a Concurrent subject the Union law prevails under Article 254. Under Article 248 the residuary power to legislate on subjects not mentioned in any list belongs to Parliament. Article 249 allows Parliament to legislate on a State List subject in the national interest if the Rajya Sabha passes a resolution supported by two-thirds of the members present and voting. Article 263 provides for an Inter-State Council, and the 101st Amendment in 2016 introduced the Goods and Services Tax and the GST Council under Article 279A.""",
qa=[("Who has the residuary power to legislate?","residuary power to legislate on subjects not mentioned in any list belongs to Parliament","factual"),
("Which law prevails if a State law conflicts with a Union law on a Concurrent subject?","the Union law prevails under Article 254","analytical"),
("Which amendment introduced the Goods and Services Tax?","101st Amendment in 2016","factual")]),
dict(title="Emergency Provisions (Articles 352-360)",
text="""Part XVIII of the Constitution contains the emergency provisions. Under Article 352 the President can proclaim a National Emergency when the security of India is threatened by war, external aggression or armed rebellion. The 44th Amendment in 1978 replaced the words internal disturbance with armed rebellion and required that the President act only on the written recommendation of the Union Cabinet. The proclamation must be approved by both Houses of Parliament within one month by a special majority, and it continues for six months unless renewed. Article 356 deals with failure of constitutional machinery in a State, known as President's Rule, which must be approved by Parliament within two months and may last up to three years in total. In S. R. Bommai v. Union of India (1994) the Supreme Court held that a proclamation under Article 356 is subject to judicial review. Article 360 provides for a Financial Emergency. During a National Emergency the rights under Article 19 are suspended, but the 44th Amendment provides that the right to life and personal liberty under Article 21 and protection in respect of conviction under Article 20 cannot be suspended.""",
qa=[("On what grounds can a National Emergency be proclaimed under Article 352?","war, external aggression or armed rebellion","factual"),
("What is President's Rule?","failure of constitutional machinery in a State, known as President's Rule","factual"),
("Which fundamental rights cannot be suspended during an Emergency?","right to life and personal liberty under Article 21 and protection in respect of conviction under Article 20 cannot be suspended","analytical")]),
dict(title="Amendment of the Constitution and the Basic Structure Doctrine (Article 368)",
text="""Article 368 in Part XX gives Parliament the power to amend the Constitution. There are three methods of amendment. Some provisions can be amended by a simple majority of Parliament, such as the creation of new States under Article 3. Most provisions require a special majority, meaning a majority of the total membership of each House and at least two-thirds of the members present and voting. Provisions that affect the federal structure, such as the election of the President, the powers of the Supreme Court and the distribution of legislative powers, need a special majority and also ratification by the legislatures of at least half of the States. After the Bill is passed, the President must give assent. In Kesavananda Bharati v. State of Kerala (1973), a bench of thirteen judges held that Parliament can amend any part of the Constitution but cannot alter its basic structure. The doctrine of the basic structure was applied again in Minerva Mills (1980), and it remains the principal limit on the amending power of Parliament.""",
qa=[("Which article gives Parliament the power to amend the Constitution?","Article 368","factual"),
("Which case established the basic structure doctrine?","Kesavananda Bharati v. State of Kerala (1973)","factual"),
("What majority is needed for most constitutional amendments?","a majority of the total membership of each House and at least two-thirds of the members present and voting","procedural")]),
dict(title="Panchayati Raj and Municipalities (73rd and 74th Amendments)",
text="""The 73rd Constitutional Amendment Act of 1992, which came into force on 24 April 1993, added Part IX to the Constitution on Panchayats (Articles 243 to 243O) and the Eleventh Schedule listing 29 subjects. It provides for a three-tier system of village, intermediate and district panchayats, although States with a population below twenty lakh may skip the intermediate level. The Gram Sabha, consisting of all registered voters in a village, is the foundation of the system. Panchayat elections are held every five years and are conducted by a State Election Commission. Not less than one-third of the seats, including the posts of chairpersons, are reserved for women, and seats are reserved for Scheduled Castes and Scheduled Tribes in proportion to their population. A State Finance Commission reviews the finances of panchayats every five years. The 74th Amendment Act of 1992 added Part IXA on Municipalities and the Twelfth Schedule listing 18 subjects, and it came into force on 1 June 1993. National Panchayati Raj Day is observed on 24 April.""",
qa=[("When did the 73rd Amendment come into force?","24 April 1993","factual"),
("What share of panchayat seats is reserved for women?","Not less than one-third of the seats","factual"),
("How do the Eleventh and Twelfth Schedules differ?","Eleventh Schedule listing 29 subjects","comparative")]),
dict(title="Constitutional Bodies and the Official Language (Articles 148, 280, 315, 324, 343)",
text="""Article 324 vests the superintendence, direction and control of elections to Parliament, State Legislatures and the offices of the President and Vice-President in the Election Commission of India, and the Chief Election Commissioner can be removed only in the same manner and on the same grounds as a judge of the Supreme Court. Article 326 provides for elections on the basis of adult suffrage. Article 148 establishes the Comptroller and Auditor-General of India, who audits the accounts of the Union and the States and is appointed by the President for a term of six years or until the age of 65, whichever is earlier. Article 315 provides for the Union Public Service Commission and Article 280 for a Finance Commission, which is constituted every five years to recommend the distribution of tax revenues between the Centre and the States. Under Article 343 the official language of the Union is Hindi in the Devanagari script, and the Official Languages Act of 1963 allows the continued use of English. The Eighth Schedule lists 22 languages.""",
qa=[("Which article gives the Election Commission control over elections?","Article 324","factual"),
("How many languages are listed in the Eighth Schedule?","22 languages","factual"),
("How often is the Finance Commission constituted?","constituted every five years","factual")]),
]
